mapper.select:
SELECT t1.subject_name, t1.grade, t1.subject_id, COUNT(t2.knowledge_id) AS first_level_knowledge FROM ms_subjects t1 LEFT JOIN ms_knowledge t2 ON t2.subject_id = t1.subject_id AND t2.parent_id = 0
where t1.grade = #{grade}
GROUP BY t1.subject_name, t1.grade HAVING COUNT(t2.knowledge_id) > 0 ORDER BY t1.subject_id
